 const fresh=commits.filter(c=>c.new).length;
 const notes=nm&&D.mailbox.ready?{title:'Notes',subtitle:ST.notes==='git'?(fresh?fresh+' commit title'+(fresh===1?'':'s')+' since the last mail, filled in below; edit as you like':'Nothing new since the last mail; the last five are filled in below, edit as you like'):ST.notes==='text'?'Write what changed, a line or two':'Just the link',leadingIcon:'file-text',
  trailing:tog(ST.notes,[['git',haveGit?'Commit titles':'Commit titles (no git)',haveGit?"pick({notes:'git',notesFor:null})":""],['text','Write',"if(ST.notes!=='text')pick({notes:'text',notesText:''})"],['-','No notes',"pick({notes:'-'})"]])}:null;
 // one stack: the questions, then Notes and its textarea inside a fold; positions follow what is open, so the corners stay 16/4
 const notesOpen=!!notes&&ST.mail,textOpen=notesOpen&&ST.notes!=='-';
 const pos=(i,n,more)=>n===1&&!more?'Single':i===0?'First':i===n-1&&!more?'Last':'Middle';
