 // under Notes, the same block either way: the commit titles that go in the mail, or the textarea to write your own
 const below=ST.notes==='-'?'':AppTextField({id:'ntx',multiline:true,rows:Math.min(10,Math.max(3,(ST.notesText||'').split('\n').length+1)),value:esc(ST.notesText),placeholder:'What changed in this version, a line or two',attrs:ST.notes==='text'?'autofocus':'',oninput:'ST.notesText=this.value;refreshCmd()'});
